'use strict';

// Image3 请求构建：唯一 messages[0]，role='user'，content 为 0—3 图片对象 + 文本对象。
// 保持参考图顺序，拒绝第 4 张图、图生图 agent、未知模型、空提示词。

const { getImage3Catalog } = require('./catalog.cjs');

const IMAGE_DATA_URL_RE = /^data:image\/(?:png|jpeg|jpg|bmp|tiff|webp|gif);base64,[A-Za-z0-9+/=]+$/;
const MAX_IMAGE_BYTES = 10 * 1024 * 1024;

function requestError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.status = 400;
  return error;
}

function validateImageInput(image) {
  if (typeof image !== 'string' || !image) {
    throw requestError('IMAGE3_IMAGE_INVALID', '参考图无效');
  }
  if (!IMAGE_DATA_URL_RE.test(image)) {
    throw requestError('IMAGE3_IMAGE_INVALID', '参考图必须是图片 Base64 data URL');
  }
  // Base64 体积粗估（data URL 中 base64 段长度 × 3/4）
  const b64 = image.slice(image.indexOf(',') + 1);
  if ((b64.length * 3) / 4 > MAX_IMAGE_BYTES) {
    throw requestError('IMAGE3_IMAGE_TOO_LARGE', '单张参考图不能超过 10MB');
  }
  return image;
}

// 构建官方请求体。options: { model, prompt, referenceImages?, size?, promptExtend?, watermark? }
function buildImage3Request(options = {}) {
  if (!options || typeof options !== 'object') {
    throw requestError('IMAGE3_PARAMS_INVALID', '参数无效');
  }
  const catalog = getImage3Catalog(options.model);

  const prompt = options.prompt;
  if (typeof prompt !== 'string' || !prompt.trim()) {
    throw requestError('IMAGE3_PROMPT_INVALID', '提示词不能为空');
  }
  if (prompt.length > 20_000) {
    throw requestError('IMAGE3_PROMPT_TOO_LONG', '提示词过长');
  }

  const referenceImages = Array.isArray(options.referenceImages) ? options.referenceImages : [];
  if (referenceImages.length > catalog.maxReferenceImages) {
    throw requestError('IMAGE3_REFERENCE_LIMIT_EXCEEDED', '参考图最多 3 张');
  }
  // 保持顺序，逐张校验
  const images = referenceImages.map(img => validateImageInput(img));

  // 图生图禁止 agent（官方 agent 为编辑代理模式，MVP 不支持）
  if (images.length > 0 && options.agent) {
    throw requestError('IMAGE3_AGENT_FORBIDDEN', '图生图禁止使用 agent');
  }

  // content：图片对象在前（按顺序），文本对象在后
  const content = [];
  for (const img of images) content.push({ image: img });
  content.push({ text: prompt });

  const parameters = {};
  if (options.size !== undefined) {
    if (typeof options.size !== 'string' || !options.size) {
      throw requestError('IMAGE3_PARAMS_INVALID', 'size 无效');
    }
    parameters.size = options.size;
  }
  parameters.prompt_extend = options.promptExtend !== false;
  parameters.watermark = options.watermark === true;
  parameters.n = 1;

  return {
    model: options.model,
    input: { messages: [{ role: 'user', content }] },
    parameters
  };
}

module.exports = { buildImage3Request, validateImageInput };
